<?php
include('../config.php');
require_once __DIR__.'/../base/GameEmailPolicy.class.php';
require_once __DIR__.'/../base/NotificationPolicy.class.php';
$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$s=new Game();if(!$s->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];$tab=(string)($_REQUEST['tab']??'inbox');$id=(int)($_REQUEST['id']??0);$notice='';$error='';
$db->query("CREATE TABLE IF NOT EXISTS game_email_messages (email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,from_uid INT NULL,from_address VARCHAR(190) NOT NULL,to_uid INT NULL,to_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,email_type VARCHAR(16) NOT NULL DEFAULT 'player',is_read TINYINT(1) NOT NULL DEFAULT 0,is_deleted TINYINT(1) NOT NULL DEFAULT 0,delivery_status VARCHAR(16) NOT NULL DEFAULT 'inbox',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,broadcast_id BIGINT UNSIGNED NULL,has_attachments TINYINT(1) NOT NULL DEFAULT 0,KEY idx_game_email_recipient(to_uid,is_deleted,created_at),KEY idx_game_email_sender(from_uid,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->query("ALTER TABLE game_email_messages ADD COLUMN IF NOT EXISTS broadcast_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS has_attachments TINYINT(1) NOT NULL DEFAULT 0");$db->query("CREATE TABLE IF NOT EXISTS game_email_attachments (attachment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,email_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,attachment_type ENUM('currency','item','equipment') NOT NULL,resource_key VARCHAR(64) NULL,asset_key VARCHAR(128) NULL,quantity BIGINT UNSIGNED NOT NULL DEFAULT 1,claimed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_mail_attachment(email_id,attachment_type,resource_key,asset_key),KEY idx_mail_attachment_claim(uid,claimed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$db->query("CREATE TABLE IF NOT EXISTS player_mail_assets (asset_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,uid INT NOT NULL,asset_type ENUM('item','equipment') NOT NULL,asset_key VARCHAR(128) NOT NULL,quantity BIGINT UNSIGNED NOT NULL DEFAULT 0,source_email_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_player_mail_asset(uid,asset_type,asset_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['email_action']??'');if($action==='send'){$to=(int)($_POST['to_uid']??0);$subject=GameEmailPolicy::cleanSubject((string)($_POST['subject']??''));$body=GameEmailPolicy::cleanBody((string)($_POST['body']??''));$type=(string)($_POST['attachment_type']??'');$resource=trim((string)($_POST['resource_key']??''));$asset=trim((string)($_POST['asset_key']??''));$qty=(int)($_POST['quantity']??0);$hasAttachment=$type!==''||$resource!==''||$asset!==''||$qty!==0;$recipient=$db->query("SELECT uname,email FROM users WHERE uid=$to LIMIT 1");$r=$recipient?$recipient->fetch_assoc():null;if(!$r||$to===$uid||$subject===''||$body===''||($hasAttachment&&!GameEmailPolicy::validAttachment($type,$resource,$asset,$qty)))$error='Choose a valid recipient, message, and optional safe attachment.';else{$from=$db->query("SELECT uname,email FROM users WHERE uid=$uid LIMIT 1");$f=$from?$from->fetch_assoc():null;$fromAddress=GameEmailPolicy::validAddress((string)($f['email']??''))?$f['email']:('player'.$uid.'@universecivilization.game');$toAddress=GameEmailPolicy::validAddress((string)($r['email']??''))?$r['email']:('player'.$to.'@universecivilization.game');$db->begin_transaction();$stmt=$db->prepare("INSERT INTO game_email_messages(from_uid,from_address,to_uid,to_address,subject,body,email_type,delivery_status,sent_at,has_attachments) VALUES(?,?,?,?,?,?, 'player','inbox',NOW(),?)");if(!$stmt){$db->rollback();$error='Email service unavailable.';}else{$stmt->bind_param('isssssi',$uid,$fromAddress,$to,$toAddress,$subject,$body,$hasAttachment);if(!$stmt->execute()){ $db->rollback();$error='Email delivery failed.';}else{$emailId=(int)$db->insert_id;if($hasAttachment){$a=$db->prepare('INSERT INTO game_email_attachments(email_id,uid,attachment_type,resource_key,asset_key,quantity) VALUES(?,?,?,?,?,?)');$a->bind_param('iisssi',$emailId,$to,$type,$resource,$asset,$qty);if(!$a->execute()){ $db->rollback();$error='Attachment could not be stored.'; } }if($error===''){$db->commit();NotificationPolicy::push($db,$to,'mail','New direct message','You received a direct message from '.($f['uname']??'another commander').'.','mail:'.$emailId,['email_id'=>$emailId]);$notice='Email and attachment sent through the game mail network.';$tab='sent';}}}}}elseif($action==='claim'){$db->begin_transaction();$q=$db->query("SELECT * FROM game_email_attachments WHERE attachment_id=$id AND uid=$uid AND claimed_at IS NULL FOR UPDATE");$a=$q?$q->fetch_assoc():null;if(!$a){$db->rollback();$error='Attachment is unavailable or already claimed.';}else{$type=$a['attachment_type'];$qty=(int)$a['quantity'];$ok=true;if($type==='currency'){$key=$db->real_escape_string((string)$a['resource_key']);$db->query("INSERT IGNORE INTO player_resources(uid) VALUES($uid)");$ok=$db->query("UPDATE player_resources SET `$key`=`$key`+$qty WHERE uid=$uid LIMIT 1");}else{$key=$db->real_escape_string((string)$a['asset_key']);$st=$db->prepare("INSERT INTO player_mail_assets(uid,asset_type,asset_key,quantity,source_email_id) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)");$emailId=(int)$a['email_id'];$st->bind_param('issii',$uid,$type,$key,$qty,$emailId);$ok=$st->execute();}if($ok){$db->query("UPDATE game_email_attachments SET claimed_at=NOW() WHERE attachment_id=$id AND uid=$uid AND claimed_at IS NULL");$db->commit();$notice='Attachment claimed successfully.';}else{$db->rollback();$error='Attachment claim failed.';}}$tab='read';}elseif($action==='read'){$db->query("UPDATE game_email_messages SET is_read=1 WHERE email_id=$id AND to_uid=$uid LIMIT 1");$tab='read';}elseif($action==='delete'){$db->query("UPDATE game_email_messages SET is_deleted=1 WHERE email_id=$id AND (to_uid=$uid OR from_uid=$uid) LIMIT 1");$notice='Email deleted.';$tab='inbox';}}
$rootAddress=GameEmailPolicy::ROOT_ADDRESS;$unreadQ=$db->query("SELECT COUNT(*) c FROM game_email_messages WHERE to_uid=$uid AND is_read=0 AND is_deleted=0");$unread=(int)($unreadQ?$unreadQ->fetch_assoc()['c']:0);$inbox=$db->query("SELECT e.*,u.uname sender_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.from_uid WHERE e.to_uid=$uid AND e.is_deleted=0 ORDER BY e.email_id DESC LIMIT 100");$sent=$db->query("SELECT e.*,u.uname recipient_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.to_uid WHERE e.from_uid=$uid AND e.is_deleted=0 ORDER BY e.email_id DESC LIMIT 100");
$h=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // EMAIL NETWORK</span><h3>Game Email</h3><p>Secure direct mail, root announcements, and claimable game attachments. Root system address: '.$h($rootAddress).'</p></div>';if($notice)echo '<div class="comm-alert">'.$h($notice).'</div>';if($error)echo '<div class="comm-alert comm-error">'.$h($error).'</div>';echo '<section class="comm-card"><p><a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'inbox\');return false">Inbox '.($unread?'('.$unread.' unread)':'').'</a> <a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'sent\');return false">Sent</a> <a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'compose\');return false">Compose</a></p>';
if($tab==='compose'){echo '<form method="post" class="admin-form-grid" action="/modules/email.php?time='.time().'&tab=compose"><input type="hidden" name="email_action" value="send"><label>Recipient UID<input type="number" name="to_uid" min="1" required></label><label>Subject<input name="subject" maxlength="190" required></label><label>Message<textarea name="body" rows="8" maxlength="20000" required></textarea></label><label>Attachment type<select name="attachment_type"><option value="">None</option><option value="currency">Currency</option><option value="item">Item</option><option value="equipment">Equipment</option></select></label><label>Currency key (currency only)<input name="resource_key" placeholder="metal, dark_matter, etc."></label><label>Item/equipment key<input name="asset_key" placeholder="blueprint.alpha or module:shield"></label><label>Quantity<input type="number" name="quantity" min="1" max="1000000000" value="1"></label><button class="comm-btn">Send Email</button></form>';}elseif($tab==='read'&&$id>0){$q=$db->query("SELECT e.*,u.uname sender_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.from_uid WHERE e.email_id=$id AND (e.to_uid=$uid OR e.from_uid=$uid) AND e.is_deleted=0 LIMIT 1");$m=$q?$q->fetch_assoc():null;if($m){$db->query("UPDATE game_email_messages SET is_read=1 WHERE email_id=$id AND to_uid=$uid LIMIT 1");$att=$db->query("SELECT * FROM game_email_attachments WHERE email_id=$id AND uid=$uid ORDER BY attachment_id");echo '<h4>'.$h($m['subject']).'</h4><p>From: '.$h($m['from_address']).' · To: '.$h($m['to_address']).'</p><div class="comm-card">'.nl2br($h($m['body'])).'</div>';if($att&&$att->num_rows){echo '<h4>Attachments</h4><div class="admin-table-wrap"><table><tr><th>Type</th><th>Key</th><th>Quantity</th><th>Status</th><th>Action</th></tr>';while($a=$att->fetch_assoc()){$key=$a['resource_key']?:$a['asset_key'];echo '<tr><td>'.$h($a['attachment_type']).'</td><td>'.$h($key).'</td><td>'.number_format((int)$a['quantity']).'</td><td>'.($a['claimed_at']?'Claimed':'Available').'</td><td>'.(!$a['claimed_at']?'<form method="post"><input type="hidden" name="email_action" value="claim"><input type="hidden" name="id" value="'.(int)$a['attachment_id'].'"><button class="comm-btn">Claim</button></form>':'—').'</td></tr>';}$att->free();echo '</table></div>';}}else echo '<p>Email not found.</p>';}elseif($tab==='sent'){echo '<div class="admin-table-wrap"><table><tr><th>To</th><th>Subject</th><th>Sent</th><th>Action</th></tr>';if($sent)while($m=$sent->fetch_assoc())echo '<tr><td>'.$h($m['recipient_name']?:$m['to_address']).'</td><td>'.$h($m['subject']).'</td><td>'.$h($m['created_at']).'</td><td><form method="post"><input type="hidden" name="email_action" value="delete"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">Delete</button></form></td></tr>';echo '</table></div>';}else{echo '<div class="admin-table-wrap"><table><tr><th>Status</th><th>From</th><th>Subject</th><th>Received</th><th>Action</th></tr>';if($inbox)while($m=$inbox->fetch_assoc())echo '<tr><td>'.((int)$m['is_read']?'Read':'Unread').'</td><td>'.$h($m['sender_name']?:$m['from_address']).'</td><td><form method="post" style="display:inline"><input type="hidden" name="email_action" value="read"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">'.$h($m['subject']).'</button></form></td><td>'.$h($m['created_at']).'</td><td><form method="post"><input type="hidden" name="email_action" value="delete"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">Delete</button></form></td></tr>';echo '</table></div>';}echo '</section></div>';$pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
